cat > /tmp/diff.pl <<'PERLEOF'
use strict; use warnings;
my $BIN='/workspace/dataset/test20_executable';
sub up   { my $s=shift; $s =~ tr/a-z/A-Z/; return $s }
sub down { my $s=shift; $s =~ tr/A-Z/a-z/; return $s }
sub cap  { my $s=shift; return '' if $s eq ''; return up(substr($s,0,1)).down(substr($s,1)) }
sub decap{ my $s=shift; return '' if $s eq ''; return down(substr($s,0,1)).substr($s,1) }
sub hex_ { join(' ', map { sprintf('%02X',ord) } split //, shift) }

my $fails=0; my $n=0;
sub test {
  my ($w,$label)=@_;
  return if $w =~ /\n/;   # newline shifts line numbering, handled separately
  open(my $fh, '-|', $BIN, $w) or die $!;
  my @l = <$fh>; close $fh;
  chomp @l;
  die "expected 20 lines got ".scalar(@l)." for $label" unless @l==20;
  my @exp = (up($w), down($w), cap($w), decap($w));
  my @got = @l[12,13,14,15];
  my @names=qw(upcase downcase capitalize decapitalize);
  $n++;
  for my $i (0..3) {
    if ($got[$i] ne $exp[$i]) {
      $fails++;
      printf("MISMATCH %-12s %-20s in=[%s] exp=[%s] got=[%s]\n",$names[$i],$label,hex_($w),hex_($exp[$i]),hex_($got[$i]));
    }
  }
}
# 1) every single byte 1..255
for my $b (1..255) { test(chr($b), "single-".sprintf('%02X',$b)); }
print "phase1 done: n=$n fails=$fails\n";
